import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';
const read=(p:string)=>readFileSync(p,'utf8');
const sql=['006_zsl2_v2_1_freeze_hardening.sql','007_zsl2_v2_1_certification_hardening.sql','008_zsl2_v2_1_rbac.sql','011_zsl2_v2_1_4_live_checkpoint_performance_compat.sql','012_zsl2_v2_1_4_set_based_performance_indexes.sql','013_zsl2_v2_1_4_territorial_pending_evidence.sql','014_zsl2_v2_1_4_zsl1_authority_and_certification_gate.sql','015_zsl2_v2_1_4_certification_authority_hardening.sql','016_zsl2_v2_1_4_activation_functions.sql','017_zsl2_v2_1_4_hud_territorial_area_evidence.sql'].map(x=>read(`database/migrations/${x}`)).join('\n');
const norm=read('src/services/normalize.service.ts');const setbased=read('src/services/setBasedNormalizer.ts');const cert=read('src/services/certification.service.ts');const auth=read('src/services/zsl1Authority.service.ts');
test('historical authority and current forward migrations coexist',()=>{assert.match(sql,/zsl2_authority_events/);assert.match(sql,/zsl2_begin_evaluation_v214/);assert.match(sql,/zsl2_activate/)});
test('normalizer reads exact bound release and ingest run',()=>{assert.match(norm,/cr\.release_id=b\.release_id/);assert.match(norm,/cr\.ingest_run_id=b\.ingest_run_id/)});
test('keyset pagination remains',()=>{assert.match(norm,/cr\.ordinal>\$3/);assert.doesNotMatch(norm,/offset/i)});
test('whole source snapshot hashing is not executed on every page',()=>{assert.match(norm,/sourceSnapshotValidated/);assert.match(norm,/SOURCE_SNAPSHOT_DRIFT_AT_COMPLETION/)});
test('set based location and relationship writes are present',()=>{assert.match(setbased,/LOCATION_BULK_UPSERT/);assert.match(setbased,/RELATIONSHIP_BULK_UPSERT/);assert.match(setbased,/from unnest/)});
test('territorial missing parents become pending evidence without county creation',()=>{assert.match(setbased,/HUD_TERRITORIAL_PENDING_BULK_INSERT/);assert.match(setbased,/PENDING_TERRITORIAL_AUTHORITY/)});
test('certification keeps HUD zero-or-one ratio policy',()=>{assert.match(cert,/least\(abs\(res_sum\),abs\(res_sum-1\)\)/);assert.match(cert,/abs\(tot_sum-1\)/)});
test('signed ZSL1 authority is pinned and live-rechecked',()=>{assert.match(auth,/PUBLIC_KEY_PIN_MISMATCH/);assert.match(auth,/verify\(null,payload/);assert.match(auth,/LIVE_AUTHORITY_POPULATION_MISMATCH/);assert.match(sql,/CERTIFIED_RELEASE_VIEW/)});
test('performance and territorial checks are mandatory',()=>{assert.match(sql,/postgres_performance_runtime_pass/);assert.match(sql,/territorial_pending_evidence_valid/);assert.match(sql,/zsl1_authority_decision_valid/)});
